        if b == 0:
            raise ZeroDivisionError("division by zero")
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def parse_expr():
        nonlocal i
        value = parse_term()
        while True:
            skip()
            if i < n and s[i] in '+-':
                op = s[i]
                i += 1
                right = parse_term()
                if op == '+':
                    value += right
                else:
                    value -= right
            else:
                break
        return value

    def parse_term():
        nonlocal i
        value = parse_factor()
        while True:
            skip()
            if i < n and s[i] in '*/':
                op = s[i]
                i += 1
                right = parse_factor()
                if op == '*':
                    value *= right
                else:
                    value = trunc_div(value, right)
            else:
                break
        return value

    def parse_factor():
        nonlocal i
        sign = 1
        while True:
            skip()
            if i < n and s[i] == '-':
                i += 1
                sign = -sign
            else:
                break
        value = parse_primary()
        return sign * value

    def parse_primary():
        nonlocal i
        skip()
        if i < n and is_digit(s[i]):
            return parse_number()
        if i < n and s[i] == '(':
            i += 1
            value = parse_expr()
            skip()
            if i < n and s[i] == ')':
                i += 1
            else:
                raise ValueError("expected ')'")
            return value
        raise ValueError("unexpected token")

    skip()
    if i >= n:
        return 0

    value = parse_expr()
    skip()
    if i != n:
