def evaluate(s: str) -> int:
    def trunc_div(a: int, b: int) -> int:
        if b == 0:
            raise ZeroDivisionError("integer division by zero")
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    values = []
    ops = []
    i = 0
    n = len(s)
    expecting_operand = True
    precedence = {"u": 4, "*": 3, "/": 3, "+": 2, "-": 2}

    def apply(op: str) -> None:
        if op == "u":
            if not values:
                raise ValueError("malformed expression")
            values.append(-values.pop())
            return
        if len(values) < 2:
            raise ValueError("malformed expression")
        b = values.pop()
        a = values.pop()
        if op == "+":
            values.append(a + b)
        elif op == "-":
            values.append(a - b)
        elif op == "*":
            values.append(a * b)
        elif op == "/":
            values.append(trunc_div(a, b))
        else:
            raise ValueError("invalid operator")

    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
            continue

        if c.isdigit():
            if not expecting_operand:
                raise ValueError("unexpected number")
            start = i
            i += 1
            while i < n and s[i].isdigit():
                i += 1
            values.append(int(s[start:i]))
            expecting_operand = False
            while ops and ops[-1] == "u":
                apply("u")
            continue

        if c == "(":
            if not expecting_operand:
                raise ValueError("unexpected '('")
            ops.append(c)
            i += 1
            expecting_operand = True
            continue

        if c == ")":
            if expecting_operand:
                raise ValueError("unexpected ')'")
            while ops and ops[-1] != "(":
                apply(ops.pop())
            if not ops:
                raise ValueError("unmatched ')'")
            ops.pop()
            expecting_operand = False
            while ops and ops[-1] == "u":
                apply("u")
            i += 1
            continue

        if c in "+-*/":
            if c in "+-" and expecting_operand:
                if c == "-":
                    ops.append("u")
                i += 1
                continue

            if expecting_operand:
                raise ValueError("unexpected operator")

            cur_prec = precedence[c]
            while ops and ops[-1] != "(" and precedence[ops[-1]] >= cur_prec:
                apply(ops.pop())
            ops.append(c)
            expecting_operand = True
            i += 1
            continue

        raise ValueError(f"unexpected character: {c!r}")

    if expecting_operand:
        raise ValueError("unexpected end of expression")

    while ops:
        op = ops.pop()
        if op == "(":
            raise ValueError("unmatched '('")
        apply(op)

    if len(values) != 1:
        raise ValueError("malformed expression")
    return values[0]
